// documentation for more info.
func (u *CloudCostUpsertBulk) Update(set func(*CloudCostUpsert)) *CloudCostUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(update *sql.UpdateSet) {
		set(&CloudCostUpsert{UpdateSet: update})
	}))
	return u
}

